#[cfg(test)]
mod instruction_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_instruction_codec() {
        let original = Instruction {
            instr_id: 123456789,
            instr_type: 1234,
            target_type: 42,
            target: "a".repeat(32),
            expiry_ns: 123456789,
            operator: "a".repeat(16),
            ts_ns: 123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(InstructionRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        Instruction::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = Instruction::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

